// Cada livro tem seis cenas/atividades e três finais escolhidos pela criança.
// Os níveis descrevem desafios de leitura, não idade nem notas escolares.
export const difficulties=[
  {id:'facil',label:'Fácil',description:'Sílabas simples, palavras e primeiras frases.'},
  {id:'medio',label:'Médio',description:'Novos sons, palavras maiores e frases completas.'},
  {id:'dificil',label:'Difícil',description:'Pistas, pequenos textos e relações entre acontecimentos.'},
  {id:'muito-dificil',label:'Muito difícil',description:'Inferências, sequência de fatos e escolhas com justificativa.'}
];

export const seq=(chapter,narration,instruction,answer,pieces,hint,extra={})=>({chapter,narration,instruction,type:'sequence',answer,pieces,hint,success:'Isso! Vamos descobrir o que acontece depois.',...extra});
export const choose=(chapter,narration,instruction,prompt,answer,options,hint,extra={})=>({chapter,narration,instruction,prompt,type:'choice',answer,choices:options.map(label=>({label})),hint,success:'Boa descoberta! Vamos continuar a história.',...extra});
export const read=(chapter,narration,text,question,answer,options,hint)=>choose(chapter,narration,question,null,answer,options,hint,{readingText:text});
export const book=(id,title,difficulty,alt,pages,finals,summary)=>({
  id:`${id}-v1`,progressKey:`conta-encanta:${id}:v1`,title,difficulty,
  cover:`${id}.webp`,coverAlt:alt,tagline:difficulties.find(d=>d.id===difficulty).description.toLocaleUpperCase('pt-BR'),
  endingTitle:'Você ajudou a contar essa aventura!',endingPrompt:'Escolha como a história vai terminar.',
  endingImage:`${id}.webp`,endingAlt:alt,summary,
  pages:pages.map((page,i)=>({id:`pagina-${i+1}`,image:`${id}.webp`,alt,...page})),
  endings:finals.map(([label,icon,sentence],i)=>({id:`final-${i+1}`,label,icon,sentence}))
});

